  return a.getUTCMonth() === b.getUTCMonth() ? `${a.getUTCDate()}–${b.getUTCDate()}-${MONS[b.getUTCMonth()]}` : `${a.getUTCDate()}-${MONS[a.getUTCMonth()]} – ${b.getUTCDate()}-${MONS[b.getUTCMonth()]}`;
